?><section class="wbce-admin-tool-shell"><header class="wbce-admin-hero"><i class="fa fa-link"></i><div class="wbce-admin-hero__content"><h2><?=htmlspecialchars($t['title'],ENT_QUOTES,'UTF-8')?></h2><p><?=htmlspecialchars($t['description'],ENT_QUOTES,'UTF-8')?></p></div></header><form id="auth-provider-form" class="content-box" method="post" action="<?=WB_URL?>/modules/auth_magic_link/save.php"><input type="hidden" name="ftan" value="<?=htmlspecialchars($admin->getFTAN(),ENT_QUOTES,'UTF-8')?>"><div class="wbce-form-grid"><label><span>Lokale Benutzer anlegen</span><input type="checkbox" name="allow_local_user_creation" value="1" <?=!empty($settings['allow_local_user_creation'])?'checked':''?>></label><label><span>Standard-Gruppen-ID</span><input class="form-control" name="default_group_id" value="<?=htmlspecialchars((string)($settings['default_group_id']??''),ENT_QUOTES,'UTF-8')?>"></label><label><span>Standard-Anzeigename</span><input class="form-control" name="default_display_name" value="<?=htmlspecialchars((string)($settings['default_display_name']??'{username}'),ENT_QUOTES,'UTF-8')?>"></label><label><span>E-Mail-Domain</span><input class="form-control" name="default_email_domain" value="<?=htmlspecialchars((string)($settings['default_email_domain']??''),ENT_QUOTES,'UTF-8')?>"></label><label><span>Standardsprache</span><input class="form-control" name="default_language" value="<?=htmlspecialchars((string)($settings['default_language']??''),ENT_QUOTES,'UTF-8')?>"></label><label><span>Standard-Zeitzone</span><input class="form-control" name="default_timezone" value="<?=htmlspecialchars((string)($settings['default_timezone']??''),ENT_QUOTES,'UTF-8')?>"></label><label><span><?=htmlspecialchars($t['enabled'],ENT_QUOTES,'UTF-8')?></span><input type="checkbox" name="enabled" value="1" <?=!empty($settings['enabled'])?'checked':''?>></label><label><span><?=htmlspecialchars($t['scope'],ENT_QUOTES,'UTF-8')?></span><select class="form-control" name="scope"><?php foreach(['all'=>'scope_all','users'=>'scope_users','disabled'=>'scope_disabled'] as $v=>$label):?><option value="<?=$v?>" <?=($settings['scope']??'disabled')===$v?'selected':''?>><?=htmlspecialchars($t[$label],ENT_QUOTES,'UTF-8')?></option><?php endforeach?></select></label><label><span><?=htmlspecialchars((string)$t['field_expires_minutes'],ENT_QUOTES,'UTF-8')?></span><input class="form-control" type="text" name="expires_minutes" value="<?=htmlspecialchars((string)($settings['expires_minutes']??'15'),ENT_QUOTES,'UTF-8')?>"></label><label><span><?=htmlspecialchars((string)$t['field_subject'],ENT_QUOTES,'UTF-8')?></span><input class="form-control" type="text" name="subject" value="<?=htmlspecialchars((string)($settings['subject']??'Ihre Anmeldung'),ENT_QUOTES,'UTF-8')?>"></label></div><button class="button wbce-admin-button" type="submit"><?=htmlspecialchars($t['save'],ENT_QUOTES,'UTF-8')?></button></form></section><script>document.getElementById('auth-provider-form').addEventListener('submit',async e=>{e.preventDefault();let r=await fetch(e.currentTarget.action,{method:'POST',body:new FormData(e.currentTarget),headers:{'X-Requested-With':'XMLHttpRequest'}}),j=await r.json();if(window.wbceToast)wbceToast(j.message,j.ok?'success':'error');if(j.ftan)e.currentTarget.ftan.value=j.ftan;});</script>